import React, { useEffect, useState } from 'react';

export default function Dashboard({user,token}){
  const [me,setMe] = useState(user);
  const [events,setEvents] = useState([]);
  const [msg,setMsg] = useState('');
  const [reports,setReports] = useState(null);
  const [activities,setActivities] = useState(null);

  useEffect(()=>{
    if (token){
      fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/dashboard/me', {headers:{Authorization:`Bearer ${token}`}})
        .then(r=>r.json()).then(d=>{ if (d.user) setMe(d.user); });
      fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/dashboard/events').then(r=>r.json()).then(setEvents);
    }
  },[token]);

  useEffect(()=>{
    if (token){
      fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/dashboard/my-activities', {headers:{Authorization:`Bearer ${token}`}})
        .then(r=>r.json()).then(setActivities).catch(()=>setActivities(null));
    }
  },[token]);

  // fetch admin reports once we have the user details and they are Admin
  useEffect(()=>{
    if (token && me && me.role === 'Admin'){
      fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/reports',{headers:{Authorization:`Bearer ${token}`}})
        .then(r=>r.json()).then(setReports).catch(()=>{});
    }
  },[token,me]);

  if (!me) return <div>Please login to see your dashboard.</div>;

  return (
    <div className="dashboard">
      <h2>{me.role} Dashboard</h2>
      <div className="grid">
        <div className="panel">
          <h3>Recognition & Badges</h3>
          {me.role!=='Admin' ? (
            <div>
              <p><strong>Name:</strong> {me.name}</p>
              <p><strong>Email:</strong> {me.email}</p>
              <p><strong>Points:</strong> {me.points}</p>
              <p><strong>Level:</strong> {me.points >= 200 ? 'Gold' : me.points >= 100 ? 'Silver' : me.points >= 50 ? 'Bronze' : me.points >= 10 ? 'Member' : 'New'}</p>
              <p><strong>Badge:</strong> {me.points >= 200 ? '🏅 Gold' : me.points >= 100 ? '🥈 Silver' : me.points >= 50 ? '🥉 Bronze' : me.points >= 10 ? '⭐ Member' : '—'}</p>
            </div>
          ) : <p>Admin account has no recognition badges.</p>}
        </div>

        <div className="panel">
          <h3>Actions</h3>
          {me.role!=='Admin' && (
            <div>
              <h4>Give Feedback</h4>
              <Feedback token={token} setMsg={setMsg} />
              <h4>Donate</h4>
              <Donate token={token} setMsg={setMsg} />
              <h4>Volunteer</h4>
              <Volunteer token={token} events={events} setMsg={setMsg} />
            </div>
          )}
          {me.role==='Admin' && (
            <div>
              <h4>Platform Reports</h4>
              <p>Admin can view feedback, donations and volunteer registrations below.</p>
              {reports ? (
                <div>
                  <h5>Recent Feedbacks</h5>
                  <ul>{reports.feedbacks && reports.feedbacks.map(f => <li key={f.id}><strong>{f.name}</strong> ({f.email}): {f.text}</li>)}</ul>
                  <h5>Recent Donations</h5>
                  <ul>{reports.donations && reports.donations.map(d => <li key={d.id}>{d.name} ({d.email}): ${d.amount}</li>)}</ul>
                  <h5>Recent Volunteers</h5>
                  <ul>{reports.volunteers && reports.volunteers.map(v => <li key={v.id}>{v.name} ({v.email}) → {v.event_title}</li>)}</ul>
                </div>
              ) : <p>Loading reports...</p>}
            </div>
          )}
          <p className="msg">{msg}</p>
        </div>

        <div className="panel">
          <h3>Events</h3>
          <div>
            {events.map(ev => (
              <div key={ev.id} style={{display:'flex',alignItems:'center',gap:12,marginBottom:10}}>
                <img src={ev.image_url||'https://via.placeholder.com/120x80'} alt={ev.title} style={{width:120,height:70,objectFit:'cover',borderRadius:6}} />
                <div style={{flex:1}}>
                  <div style={{fontWeight:600}}>{ev.title}</div>
                  <div style={{color:'#666',fontSize:13}}>{ev.description && ev.description.slice(0,120)}</div>
                </div>
                <div>
                  {activities && activities.volunteers && activities.volunteers.find(v=>v.event_id===ev.id) ? (
                    <button disabled style={{padding:'8px 10px',borderRadius:8}}>Joined</button>
                  ) : (
                    <button onClick={async ()=>{
                      if (!token){ setMsg('Please login to join'); return; }
                      const res = await fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/volunteer',{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${token}`},body:JSON.stringify({event_id:ev.id})});
                      const d = await res.json(); setMsg(d.message || 'Registered');
                      // refresh activities
                      fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/dashboard/my-activities', {headers:{Authorization:`Bearer ${token}`}})
                        .then(r=>r.json()).then(setActivities).catch(()=>{});
                    }} style={{padding:'8px 10px',borderRadius:8,background:'#0b5aaa',color:'white',border:'none'}}>Join</button>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

function Feedback({token,setMsg}){
  const [text,setText] = useState('');
  async function submit(e){ e.preventDefault(); const res = await fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/feedback',{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${token}`},body:JSON.stringify({text})}); setMsg((await res.json()).message || 'Feedback sent'); }
  return (<form onSubmit={submit}><textarea value={text} onChange={e=>setText(e.target.value)} placeholder="Write feedback"/><button>Send Feedback</button></form>);
}

function Donate({token,setMsg}){
