function Volunteer({token,events,setMsg}){
  const [eventId,setEventId] = useState('');
  async function submit(e){ e.preventDefault(); const res = await fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/volunteer',{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${token}`},body:JSON.stringify({event_id:eventId})}); setMsg((await res.json()).message || 'Registered'); }
  return (
    <form onSubmit={submit}>
      <select value={eventId} onChange={e=>setEventId(e.target.value)}>
        <option value="">Select event</option>
        {events.map(ev=>(<option key={ev.id} value={ev.id}>{ev.title}</option>))}
      </select>
      <button>Sign Up</button>
    </form>
  );
}
